from solution import add_months


def test_example_basic():
    assert add_months('2026-01-15', 1) == '2026-02-15'


def test_example_end_of_month():
    assert add_months('2026-01-31', 1) == '2026-02-28'


def test_zero():
    assert add_months('2026-03-10', 0) == '2026-03-10'


def test_zero_last_day():
    assert add_months('2026-02-28', 0) == '2026-02-28'


def test_last_day_feb_to_march():
    # Feb 28 is last day -> Mar 31
    assert add_months('2026-02-28', 1) == '2026-03-31'


def test_last_day_leap_feb_to_march():
    assert add_months('2024-02-29', 1) == '2024-03-31'


def test_last_day_to_leap_feb():
    assert add_months('2023-01-31', 13) == '2024-02-29'


def test_last_day_30_to_31():
    assert add_months('2026-04-30', 1) == '2026-05-31'


def test_non_last_day_short_month():
    assert add_months('2026-01-30', 1) == '2026-02-28'
    assert add_months('2024-01-30', 1) == '2024-02-29'


def test_non_last_day_keeps_day():
    # Feb 28 in leap year is not last day
    assert add_months('2024-02-28', 12) == '2025-02-28'
    assert add_months('2024-02-28', 1) == '2024-03-28'


def test_negative():
    assert add_months('2026-03-31', -1) == '2026-02-28'
    assert add_months('2026-01-15', -1) == '2025-12-15'


def test_negative_year_cross():
    assert add_months('2026-01-31', -2) == '2025-11-30'


def test_large_positive():
    assert add_months('2026-01-15', 24) == '2028-01-15'
    assert add_months('2026-12-31', 1) == '2027-01-31'


def test_large_negative():
    assert add_months('2026-06-15', -30) == '2023-12-15'


def test_december_boundary():
    assert add_months('2026-11-30', 1) == '2026-12-31'
    assert add_months('2026-01-31', 11) == '2026-12-31'


def test_year_padding():
    assert add_months('0999-12-15', 1) == '1000-01-15'
    assert add_months('0100-03-15', 0) == '0100-03-15'


def test_century_non_leap():
    assert add_months('2000-01-31', 1) == '2000-02-29'
    assert add_months('1900-01-31', 1) == '1900-02-28'

from solution import add_months

def test_basic():
    assert add_months('2026-01-15', 1) == '2026-02-15'

def test_last_day_to_feb():
    assert add_months('2026-01-31', 1) == '2026-02-28'

def test_last_day_leap():
    assert add_months('2024-01-31', 1) == '2024-02-29'

def test_last_day_feb_to_31():
    assert add_months('2026-02-28', 1) == '2026-03-31'

def test_last_day_leap_feb_to_march():
    assert add_months('2024-02-29', 1) == '2024-03-31'

def test_feb28_leap_not_last():
    assert add_months('2024-02-28', 12) == '2025-02-28'
    assert add_months('2024-02-28', 1) == '2024-03-28'

def test_last_day_april_to_may():
    assert add_months('2026-04-30', 1) == '2026-05-31'

def test_not_last_day_clamp():
    assert add_months('2026-01-30', 1) == '2026-02-28'
    assert add_months('2026-03-30', -1) == '2026-02-28'

def test_zero():
    assert add_months('2026-03-17', 0) == '2026-03-17'
    assert add_months('2026-04-30', 0) == '2026-04-30'

def test_negative_year_rollover():
    assert add_months('2026-01-15', -1) == '2025-12-15'
    assert add_months('2026-01-15', -13) == '2024-12-15'

def test_positive_year_rollover():
    assert add_months('2026-12-31', 1) == '2027-01-31'
    assert add_months('2026-11-30', 2) == '2027-01-31'

def test_large():
    assert add_months('2026-01-31', 120) == '2036-01-31'
    assert add_months('2026-01-31', -24) == '2024-01-31'

def test_multiple_of_12_negative():
    assert add_months('2026-12-15', -12) == '2025-12-15'

def test_leap_century():
    assert add_months('2000-01-31', 1) == '2000-02-29'
    assert add_months('1900-01-31', 1) == '1900-02-28'

def test_pad_year():
    assert add_months('0999-12-31', 1) == '1000-01-31'
